const { useState, useEffect, useRef } = React;

// Main App Component
function App() {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [posts, setPosts] = useState([]);
  const [campaigns, setCampaigns] = useState([]);
  const [analytics, setAnalytics] = useState({});
  const [isGenerating, setIsGenerating] = useState(false);

  return (
    <div className="app">
      <Sidebar activeTab={activeTab} setActiveTab={setActiveTab} />
      <main className="main-content">
        <Header />
        <div className="content">
          {activeTab === 'dashboard' && <Dashboard analytics={analytics} />}
          {activeTab === 'content' && <ContentCreator posts={posts} setPosts={setPosts} isGenerating={isGenerating} setIsGenerating={setIsGenerating} />}
          {activeTab === 'schedule' && <Scheduler posts={posts} />}
          {activeTab === 'analytics' && <Analytics analytics={analytics} />}
          {activeTab === 'campaigns' && <Campaigns campaigns={campaigns} setCampaigns={setCampaigns} />}
          {activeTab === 'settings' && <Settings />}
        </div>
      </main>
    </div>
  );
}

// Sidebar Navigation
function Sidebar({ activeTab, setActiveTab }) {
  const menuItems = [
    { id: 'dashboard', icon: 'fas fa-chart-line', label: 'Dashboard' },
    { id: 'content', icon: 'fas fa-edit', label: 'Content Creator' },
    { id: 'schedule', icon: 'fas fa-calendar', label: 'Scheduler' },
    { id: 'analytics', icon: 'fas fa-chart-bar', label: 'Analytics' },
    { id: 'campaigns', icon: 'fas fa-bullhorn', label: 'Campaigns' },
    { id: 'settings', icon: 'fas fa-cog', label: 'Settings' }
  ];

  return (
    <aside className="sidebar">
      <div className="logo">
        <i className="fas fa-robot"></i>
        <span>AI Social Manager</span>
      </div>
      <nav>
        {menuItems.map(item => (
          <button
            key={item.id}
            className={`nav-item ${activeTab === item.id ? 'active' : ''}`}
            onClick={() => setActiveTab(item.id)}
          >
            <i className={item.icon}></i>
            <span>{item.label}</span>
          </button>
        ))}
      </nav>
    </aside>
  );
}

// Header Component
function Header() {
  return (
    <header className="header">
      <div className="header-content">
        <h1>AI Social Media Manager</h1>
        <div className="header-actions">
          <button className="btn btn-primary">
            <i className="fas fa-plus"></i>
            Quick Post
          </button>
          <div className="user-menu">
            <img src="https://via.placeholder.com/32" alt="User" className="avatar" />
          </div>
        </div>
      </div>
    </header>
  );
}

// Dashboard Component
function Dashboard({ analytics }) {
  const stats = [
    { title: 'Total Posts', value: '247', change: '+12%', icon: 'fas fa-edit' },
    { title: 'Engagement Rate', value: '4.2%', change: '+0.8%', icon: 'fas fa-heart' },
    { title: 'Followers', value: '12.5K', change: '+156', icon: 'fas fa-users' },
    { title: 'Reach', value: '45.2K', change: '+23%', icon: 'fas fa-eye' }
  ];

  return (
    <div className="dashboard">
      <div className="stats-grid">
        {stats.map((stat, index) => (
          <div key={index} className="stat-card">
            <div className="stat-icon">
              <i className={stat.icon}></i>
            </div>
            <div className="stat-content">
              <h3>{stat.value}</h3>
              <p>{stat.title}</p>
              <span className="stat-change positive">{stat.change}</span>
            </div>
          </div>
        ))}
      </div>

      <div className="dashboard-grid">
        <div className="card">
          <h3>Recent Posts Performance</h3>
          <div className="chart-placeholder">
            <canvas id="performanceChart" width="400" height="200"></canvas>
          </div>
        </div>

        <div className="card">
          <h3>Upcoming Posts</h3>
          <div className="upcoming-posts">
            <div className="post-item">
              <div className="post-time">Today 2:00 PM</div>
              <div className="post-content">"Exciting product launch coming soon! 🚀"</div>
              <div className="post-platforms">
                <span className="platform twitter">Twitter</span>
                <span className="platform linkedin">LinkedIn</span>
              </div>
            </div>
            <div className="post-item">
              <div className="post-time">Tomorrow 10:00 AM</div>
              <div className="post-content">"Behind the scenes of our development process"</div>
              <div className="post-platforms">
                <span className="platform instagram">Instagram</span>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

// Content Creator Component
function ContentCreator({ posts, setPosts, isGenerating, setIsGenerating }) {
  const [prompt, setPrompt] = useState('');
  const [selectedPlatforms, setSelectedPlatforms] = useState(['twitter']);
  const [contentType, setContentType] = useState('promotional');
  const [generatedContent, setGeneratedContent] = useState(null);

  const platforms = [
    { id: 'twitter', name: 'Twitter', icon: 'fab fa-twitter' },
    { id: 'linkedin', name: 'LinkedIn', icon: 'fab fa-linkedin' },
    { id: 'instagram', name: 'Instagram', icon: 'fab fa-instagram' },
    { id: 'facebook', name: 'Facebook', icon: 'fab fa-facebook' }
  ];

  const contentTypes = [
    'promotional', 'educational', 'entertaining', 'news', 'behind-the-scenes'
  ];

  const generateContent = async () => {
    setIsGenerating(true);

    // Simulate AI content generation
    setTimeout(() => {
      const generated = {
        text: `🚀 ${prompt} - Crafted with AI precision for maximum engagement! #Innovation #AI #SocialMedia`,
        hashtags: ['#Innovation', '#AI', '#SocialMedia', '#TechTrends'],
        platforms: selectedPlatforms,
        suggestedTime: 'Today at 2:00 PM',
        estimatedReach: '2.5K - 5K users'
      };
      setGeneratedContent(generated);
      setIsGenerating(false);
    }, 2000);
  };

  return (
    <div className="content-creator">
      <div className="creator-form">
        <div className="card">
          <h3>AI Content Generator</h3>

          <div className="form-group">
            <label>Content Prompt</label>
            <textarea
              value={prompt}
              onChange={(e) => setPrompt(e.target.value)}
              placeholder="Describe what you want to post about..."
              rows="3"
            />
          </div>

          <div className="form-group">
            <label>Content Type</label>
            <select value={contentType} onChange={(e) => setContentType(e.target.value)}>
              {contentTypes.map(type => (
                <option key={type} value={type}>
                  {type.charAt(0).toUpperCase() + type.slice(1)}
                </option>
              ))}
            </select>
          </div>

          <div className="form-group">
            <label>Target Platforms</label>
            <div className="platform-selector">
              {platforms.map(platform => (
                <label key={platform.id} className="platform-option">
                  <input
                    type="checkbox"
                    checked={selectedPlatforms.includes(platform.id)}
                    onChange={(e) => {
                      if (e.target.checked) {
                        setSelectedPlatforms([...selectedPlatforms, platform.id]);
                      } else {
                        setSelectedPlatforms(selectedPlatforms.filter(p => p !== platform.id));
                      }
                    }}
                  />
                  <i className={platform.icon}></i>
                  {platform.name}
                </label>
              ))}
            </div>
          </div>

          <button
            className="btn btn-primary btn-large"
            onClick={generateContent}
            disabled={!prompt || isGenerating}
          >
            {isGenerating ? (
              <>
                <i className="fas fa-spinner fa-spin"></i>
                Generating...
              </>
            ) : (
              <>
                <i className="fas fa-magic"></i>
                Generate Content
              </>
            )}
          </button>
        </div>
      </div>

      {generatedContent && (
        <div className="generated-content">
          <div className="card">
            <h3>Generated Content</h3>

            <div className="content-preview">
              <div className="content-text">{generatedContent.text}</div>

              <div className="content-meta">
                <div className="hashtags">
                  {generatedContent.hashtags.map((tag, index) => (
                    <span key={index} className="hashtag">{tag}</span>
                  ))}
                </div>

                <div className="content-stats">
                  <div className="stat">
                    <i className="fas fa-clock"></i>
                    {generatedContent.suggestedTime}
                  </div>
                  <div className="stat">
                    <i className="fas fa-users"></i>
                    {generatedContent.estimatedReach}
                  </div>
                </div>
              </div>
            </div>

            <div className="content-actions">
              <button className="btn btn-secondary">
                <i className="fas fa-edit"></i>
                Edit
              </button>
              <button className="btn btn-primary">
                <i className="fas fa-calendar"></i>
                Schedule
              </button>
              <button className="btn btn-success">
                <i className="fas fa-paper-plane"></i>
                Post Now
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

// Scheduler Component
function Scheduler({ posts }) {
  return (
    <div className="scheduler">
      <div className="card">
        <h3>Content Scheduler</h3>
        <p>Schedule and manage your social media posts across all platforms.</p>

        <div className="calendar-view">
          <div className="calendar-header">
            <h4>December 2024</h4>
            <div className="calendar-nav">
              <button><i className="fas fa-chevron-left"></i></button>
              <button><i className="fas fa-chevron-right"></i></button>
            </div>
          </div>

          <div className="calendar-grid">
            {/* Calendar implementation would go here */}
            <div className="calendar-placeholder">
              Calendar view coming soon...
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

// Analytics Component
function Analytics({ analytics }) {
  return (
    <div className="analytics">
      <div className="card">
        <h3>Analytics Dashboard</h3>
        <p>Track your social media performance and engagement metrics.</p>

        <div className="analytics-charts">
          <div className="chart-container">
            <h4>Engagement Over Time</h4>
            <canvas id="engagementChart" width="400" height="200"></canvas>
          </div>

          <div className="chart-container">
            <h4>Platform Performance</h4>
            <canvas id="platformChart" width="400" height="200"></canvas>
          </div>
        </div>
      </div>
    </div>
  );
}

// Campaigns Component
function Campaigns({ campaigns, setCampaigns }) {
  return (
    <div className="campaigns">
      <div className="card">
        <h3>Campaign Management</h3>
        <p>Create and manage marketing campaigns across platforms.</p>

        <button className="btn btn-primary">
          <i className="fas fa-plus"></i>
          Create Campaign
        </button>

        <div className="campaigns-list">
          <div className="campaign-item">
            <h4>Product Launch Campaign</h4>
            <p>Multi-platform campaign for new product announcement</p>
            <div className="campaign-stats">
              <span>12 posts</span>
              <span>4 platforms</span>
              <span>Running</span>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

// Settings Component
function Settings() {
  return (
    <div className="settings">
      <div className="card">
        <h3>Settings & Configuration</h3>

        <div className="settings-section">
          <h4>API Keys</h4>
          <div className="api-keys">
            <div className="api-key-item">
              <label>OpenAI API Key</label>
              <input type="password" placeholder="sk-..." />
              <span className="status disconnected">Disconnected</span>
            </div>
            <div className="api-key-item">
              <label>Twitter API Key</label>
              <input type="password" placeholder="Enter your Twitter API key" />
              <span className="status disconnected">Disconnected</span>
            </div>
            <div className="api-key-item">
              <label>LinkedIn API Key</label>
              <input type="password" placeholder="Enter your LinkedIn API key" />
              <span className="status disconnected">Disconnected</span>
            </div>
          </div>
        </div>

        <div className="settings-section">
          <h4>Brand Voice</h4>
          <textarea placeholder="Describe your brand voice and tone..." rows="3"></textarea>
        </div>

        <div className="settings-section">
          <h4>Posting Schedule</h4>
          <div className="schedule-settings">
            <label>
              <input type="checkbox" /> Auto-schedule posts for optimal times
            </label>
            <label>
              <input type="checkbox" /> Send notifications before posting
            </label>
          </div>
        </div>

        <button className="btn btn-primary">Save Settings</button>
      </div>
    </div>
  );
}

// Render the app
ReactDOM.render(<App />, document.getElementById('root'));

