import express from 'express';
import cors from 'cors';
import dotenv from 'dotenv';
import path from 'path';
import { fileURLToPath } from 'url';
import { AIService } from './services/ai-service.js';
import { SocialMediaService } from './services/social-media-service.js';
import { DatabaseService } from './services/database-service.js';
import { SchedulerService } from './services/scheduler-service.js';
import { AnalyticsService } from './services/analytics-service.js';

dotenv.config();

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const app = express();
const PORT = process.env.PORT || 3000;

// Initialize services
const db = new DatabaseService();
const aiService = new AIService();
const socialMediaService = new SocialMediaService();
const schedulerService = new SchedulerService();
const analyticsService = new AnalyticsService();

// Middleware
app.use(cors());
app.use(express.json());
app.use(express.static('.'));

// Initialize database
await db.initialize();

// Routes

// Serve the main app
app.get('/', (req, res) => {
  res.sendFile(path.join(__dirname, 'index.html'));
});

// AI Content Generation
app.post('/api/generate-content', async (req, res) => {
  try {
    const { prompt, contentType, platforms, brandVoice } = req.body;

    const content = await aiService.generateContent({
      prompt,
      contentType,
      platforms,
      brandVoice
    });

    res.json({ success: true, content });
  } catch (error) {
    console.error('Content generation error:', error);
    res.status(500).json({ success: false, error: error.message });
  }
});

// Schedule Post
app.post('/api/schedule-post', async (req, res) => {
  try {
    const { content, platforms, scheduledTime, userId } = req.body;

    const scheduledPost = await schedulerService.schedulePost({
      content,
      platforms,
      scheduledTime,
      userId
    });

    res.json({ success: true, scheduledPost });
  } catch (error) {
    console.error('Scheduling error:', error);
    res.status(500).json({ success: false, error: error.message });
  }
});

// Post Now
app.post('/api/post-now', async (req, res) => {
  try {
    const { content, platforms, userId } = req.body;

    const results = await socialMediaService.postToMultiplePlatforms({
      content,
      platforms,
      userId
    });

    res.json({ success: true, results });
  } catch (error) {
    console.error('Posting error:', error);
    res.status(500).json({ success: false, error: error.message });
  }
});

// Get Analytics
app.get('/api/analytics/:userId', async (req, res) => {
  try {
    const { userId } = req.params;
    const { timeframe = '30d' } = req.query;

    const analytics = await analyticsService.getAnalytics(userId, timeframe);

    res.json({ success: true, analytics });
  } catch (error) {
    console.error('Analytics error:', error);
    res.status(500).json({ success: false, error: error.message });
  }
});

// Get Scheduled Posts
app.get('/api/scheduled-posts/:userId', async (req, res) => {
  try {
    const { userId } = req.params;

    const posts = await schedulerService.getScheduledPosts(userId);

    res.json({ success: true, posts });
  } catch (error) {
    console.error('Fetch scheduled posts error:', error);
    res.status(500).json({ success: false, error: error.message });
  }
});

// Save API Keys
app.post('/api/save-keys', async (req, res) => {
  try {
    const { userId, keys } = req.body;

    await db.saveUserKeys(userId, keys);

    res.json({ success: true, message: 'API keys saved successfully' });
  } catch (error) {
    console.error('Save keys error:', error);
    res.status(500).json({ success: false, error: error.message });
  }
});

// Health check
app.get('/api/health', (req, res) => {
  res.json({ 
    success: true, 
    status: 'running',
    timestamp: new Date().toISOString(),
    services: {
      database: db.isConnected(),
      ai: aiService.isConfigured(),
      socialMedia: socialMediaService.isConfigured()
    }
  });
});

app.listen(PORT, () => {
  console.log(`🚀 AI Social Media Manager running on http://localhost:${PORT}`);
  console.log('🔧 Configure your API keys in the Settings tab to get started!');
});

