#!/usr/bin/env node

import fs from 'fs';
import path from 'path';
import readline from 'readline';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout
});

function question(prompt) {
  return new Promise((resolve) => {
    rl.question(prompt, resolve);
  });
}

async function setup() {
  console.log('🚀 AI Social Media Manager Setup');
  console.log('================================\n');

  console.log('This setup will help you configure your API keys and get started.\n');

  // Create .env file if it doesn't exist
  const envPath = path.join(__dirname, '.env');
  const envExamplePath = path.join(__dirname, '.env.example');

  if (!fs.existsSync(envPath)) {
    console.log('📝 Creating .env file from template...');
    fs.copyFileSync(envExamplePath, envPath);
    console.log('✅ .env file created\n');
  }

  console.log('🔑 API Key Configuration');
  console.log('========================\n');

  console.log('You\'ll need to obtain API keys from the following services:');
  console.log('1. OpenAI (required for AI content generation)');
  console.log('2. Twitter/X Developer Account');
  console.log('3. LinkedIn Developer Program');
  console.log('4. Meta Developer (for Instagram/Facebook)');
  console.log('5. TikTok for Developers');
  console.log('6. YouTube Data API\n');

  const configureNow = await question('Would you like to configure API keys now? (y/n): ');

  if (configureNow.toLowerCase() === 'y') {
    let envContent = fs.readFileSync(envPath, 'utf8');

    // OpenAI Configuration
    console.log('\n🤖 OpenAI Configuration');
    const openaiKey = await question('Enter your OpenAI API key (sk-...): ');
    if (openaiKey) {
      envContent = envContent.replace('sk-your-openai-api-key-here', openaiKey);
    }

    // Twitter Configuration
    console.log('\n🐦 Twitter/X Configuration');
    const twitterKey = await question('Enter your Twitter API key (optional, press Enter to skip): ');
    if (twitterKey) {
      envContent = envContent.replace('your-twitter-api-key', twitterKey);

      const twitterSecret = await question('Enter your Twitter API secret: ');
      const twitterToken = await question('Enter your Twitter access token: ');
      const twitterTokenSecret = await question('Enter your Twitter access token secret: ');

      envContent = envContent.replace('your-twitter-api-secret', twitterSecret);
      envContent = envContent.replace('your-twitter-access-token', twitterToken);
      envContent = envContent.replace('your-twitter-access-token-secret', twitterTokenSecret);
    }

    // LinkedIn Configuration
    console.log('\n💼 LinkedIn Configuration');
    const linkedinClient = await question('Enter your LinkedIn Client ID (optional, press Enter to skip): ');
    if (linkedinClient) {
      envContent = envContent.replace('your-linkedin-client-id', linkedinClient);

      const linkedinSecret = await question('Enter your LinkedIn Client Secret: ');
      const linkedinToken = await question('Enter your LinkedIn Access Token: ');

      envContent = envContent.replace('your-linkedin-client-secret', linkedinSecret);
      envContent = envContent.replace('your-linkedin-access-token', linkedinToken);
    }

    // Brand Voice Configuration
    console.log('\n🎨 Brand Voice Configuration');
    const brandVoice = await question('Describe your brand voice (e.g., professional, friendly, innovative): ');
    if (brandVoice) {
      envContent = envContent.replace('professional, friendly, innovative', brandVoice);
    }

    // Save updated .env file
    fs.writeFileSync(envPath, envContent);
    console.log('\n✅ Configuration saved to .env file');
  }

  // Create necessary directories
  console.log('\n📁 Creating directories...');
  const directories = ['data', 'uploads', 'logs'];
  directories.forEach(dir => {
    const dirPath = path.join(__dirname, dir);
    if (!fs.existsSync(dirPath)) {
      fs.mkdirSync(dirPath, { recursive: true });
      console.log(`✅ Created ${dir}/ directory`);
    }
  });

  console.log('\n🎉 Setup Complete!');
  console.log('==================\n');
  console.log('Next steps:');
  console.log('1. Run `npm start` to start the application');
  console.log('2. Open http://localhost:3000 in your browser');
  console.log('3. Configure additional API keys in the Settings tab');
  console.log('4. Start creating amazing social media content with AI!\n');

  console.log('📚 Documentation:');
  console.log('- API Keys Guide: Check the README.md for detailed setup instructions');
  console.log('- Platform Setup: Visit each platform\'s developer documentation');
  console.log('- Support: Open an issue on GitHub if you need help\n');

  rl.close();
}

setup().catch(console.error);
